//! Cache-backed original factories; production scheduling is tested separately.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::{amulet_stringing,ordinary_stringing,battlestaff_assembly};
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn thirty_eight_actual_items_and_four_hundred_twenty_one_refusals(){
 let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let seq=symbols::load(&[Path::new(&dir)],"seq",None).unwrap();let stat=symbols::load(&[Path::new(&dir)],"stat",None).unwrap();let spot=symbols::load(&[Path::new(&dir)],"spotanim",None).unwrap();
 let cache=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&cache),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let stats=cache.files(2,200,None).unwrap().unwrap();
 let groups=[vec![("ball_of_wool",1759),("unstrung_gold_amulet",1673),("strung_gold_amulet",1692),("unstrung_sapphire_amulet",1675),("strung_sapphire_amulet",1694),("unstrung_emerald_amulet",1677),("strung_emerald_amulet",1696),("unstrung_ruby_amulet",1679),("strung_ruby_amulet",1698),("unstrung_diamond_amulet",1681),("strung_diamond_amulet",1700),("unstrung_dragonstone_amulet",1683),("strung_dragonstone_amulet",1702),("unstrung_onyx_amulet",6579),("strung_onyx_amulet",6581),("unstrung_zenyte_amulet",19501),("zenyte_amulet",19541),("unstrung_opal_amulet",21099),("strung_opal_amulet",21108),("unstrung_jade_amulet",21102),("strung_jade_amulet",21111),("unstrung_topaz_amulet",21105),("strung_topaz_amulet",21114)],vec![("ball_of_wool",1759),("nostringstar",1714),("stringstar",1716),("nostringsnake",1720),("stringsnake",1722),("hunting_rabbit_foot",10134),("hunting_strung_rabbit_foot",10132)],vec![("battlestaff",1391),("water_orb",571),("earth_orb",575),("fire_orb",569),("air_orb",573),("water_battlestaff",1395),("earth_battlestaff",1399),("fire_battlestaff",1393),("air_battlestaff",1397)]];
 let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for group in &groups{for(_,id)in group{defs.items.insert(*id as u32,gielinor_cache::definitions::ItemType::decode(&items[&(*id as u32)]).unwrap());}}assert_eq!(defs.items.len(),38);defs.stats.insert(12,gielinor_cache::definitions::StatType::decode(&stats[&12]).unwrap());
 let amulets=amulet_stringing(&objects,&stat,&defs).unwrap();assert_eq!(amulets.len(),11);for(i,(r,(raw,out)))in amulets.into_iter().zip([(1673,1692),(1675,1694),(1677,1696),(1679,1698),(1681,1700),(1683,1702),(6579,6581),(19501,19541),(21099,21108),(21102,21111),(21105,21114)]).enumerate(){assert_eq!((r.first,r.second,r.output,r.skill,r.level,r.base_xp,r.members),(1759,raw,out,12,1,4,i>=5));}
 let ordinary=ordinary_stringing(&objects,&stat,&defs).unwrap();assert_eq!(ordinary.len(),3);for(r,(raw,out,level,member))in ordinary.into_iter().zip([(1714,1716,1,false),(1720,1722,1,true),(10134,10132,37,true)]){assert_eq!((r.first,r.second,r.output,r.skill,r.level,r.base_xp,r.members),(1759,raw,out,12,level,4,member));}
 let staff=battlestaff_assembly(&objects,&seq,&spot,&stat,&defs).unwrap();assert_eq!(staff.len(),4);for(r,(raw,out,level,xp,effect))in staff.into_iter().zip([(571,1395,54,1000,1370),(575,1399,58,1125,1371),(569,1393,62,1250,1372),(573,1397,66,1375,306)]){assert_eq!((r.recipe.first,r.recipe.second,r.recipe.output,r.recipe.skill,r.recipe.level,r.recipe.base_xp,r.recipe.members),(1391,raw,out,12,level,0,true));assert_eq!((r.xp_tenths,r.ticks,r.animation,r.spot),(xp,2,Some(7531),Some(effect)));}
 let refuses=|kind:usize,o:&BTreeMap<String,i32>,s:&BTreeMap<String,i32>,d:&Definitions|match kind{0=>amulet_stringing(o,s,d).is_err(),1=>ordinary_stringing(o,s,d).is_err(),_=>battlestaff_assembly(o,&seq,&spot,s,d).is_err()};let mut refused=0;
 for(kind,group)in groups.iter().enumerate(){for(symbol,id)in group{for case in 0..10{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(*id as u32));},1=>d.items.get_mut(&(*id as u32)).unwrap().name="Wrong".into(),2=>{let x=d.items.get_mut(&(*id as u32)).unwrap();x.members=!x.members;},3=>d.items.get_mut(&(*id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(*id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(*id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(*id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(*id as u32)).unwrap().transform.template=1,8=>{o.insert((*symbol).into(),id+100000);},_=>{o.remove(*symbol);}}assert!(refuses(kind,&o,&stat,&d),"kind{kind} {symbol} mode{case}");refused+=1;}}
 for case in 0..7{let mut d=copy(&defs);let mut s=stat.clone();match case{0=>{s.remove("crafting");},1=>{s.insert("crafting".into(),13);},2=>{d.stats.remove(&12);},3=>d.stats.get_mut(&12).unwrap().name="Wrong".into(),4=>d.stats.get_mut(&12).unwrap().unreleased=true,5=>d.stats.get_mut(&12).unwrap().min_level=0,_=>d.stats.get_mut(&12).unwrap().max_level=98}assert!(refuses(kind,&objects,&s,&d));refused+=1;}}
 for alias in[false,true]{let mut q=seq.clone();if alias{q.insert("human_battlestaff_crafting".into(),7532);}else{q.remove("human_battlestaff_crafting");}assert!(battlestaff_assembly(&objects,&q,&spot,&stat,&defs).is_err());refused+=1;}
 for symbol in["battlestaff_water_crafting_spotanim","battlestaff_earth_crafting_spotanim","battlestaff_fire_crafting_spotanim","battlestaff_air_crafting_spotanim"]{for alias in[false,true]{let mut p=spot.clone();if alias{p.insert(symbol.into(),9999);}else{p.remove(symbol);}assert!(battlestaff_assembly(&objects,&seq,&p,&stat,&defs).is_err());refused+=1;}}
 assert_eq!(refused,421);println!("PG_PAIR_BINDINGS unique_items=38 profiles=18 refused=421");
}
